sap.ui.define([], function () {
  "use strict";
  return {
    getPredefinedValuesForCreateExtension: function (oSmartFilterBar) {
      const filterData = oSmartFilterBar.getFilterData();
      const values = {};
      if (filterData.CustomerID && filterData.CustomerID.items && filterData.CustomerID.items.length === 1) {
        values.CustomerID = filterData.CustomerID.items[0].key;
      }
      return values;
    }
  };
});
